	public static ClickyInkLiveNote LiveNote(params (string Text, double At, bool IsEdit)[] versions)
	{
		ClickyInkLiveNote clickyInkLiveNote = new ClickyInkLiveNote();
		for (int i = 0; i < versions.Length; i++)
		{
			var (source, time, isEdit) = versions[i];
			clickyInkLiveNote.Apply(ClickyInkParser.Parse(source), time, isEdit);
		}
		return clickyInkLiveNote;
	}

	public static ClickyInkLiveNote LiveNote(string text)
	{
		return LiveNote((text, 0.0, false));
	}

	public static ClickyHomeInkNote HomeInkNote(ClickyInkLiveNote note, double clock, DateTimeOffset? now = null)
	{
		return new ClickyHomeInkNote(note, (now ?? DateTimeOffset.Now).AddSeconds(0.0 - clock));
	}

